fn a_left(r:f32,g:f32,b:f32)->f32{ (r*KR + g*KG) + b*KB }          // model A, left-assoc  (matches disasm)
fn a_right(r:f32,g:f32,b:f32)->f32{ r*KR + (g*KG + b*KB) }         // alt association
fn a_fma(r:f32,g:f32,b:f32)->f32{ (b*KB).mul_add(1.0, r*KR+g*KG) } // placeholder
fn b_mod(r:f32,g:f32,b:f32)->f32{ ((r as f64)*0.2126 + (g as f64)*0.7152 + (b as f64)*0.0722) as f32 }
fn c_mod(r:f32,g:f32,b:f32)->f64{ (r as f64)*0.2126 + (g as f64)*0.7152 + (b as f64)*0.0722 }
fn g6(x:f64)->String{ if x==0.0 {return format!("{}", if x.is_sign_negative(){"-0"}else{"0"});} format!("{:.5e}", x) }
