    let mut rnd = move || { s ^= s<<13; s^=s>>7; s^=s<<17; s };
    let mut out=String::new();
    let mut kinds=[0usize;4];
    let mut tries=0;
    while tries < 30_000_000 && (kinds[0]<8||kinds[1]<8||kinds[2]<8||kinds[3]<8) {
        tries+=1;
        // choose a domain
        let dom = (rnd()%4) as usize;
        let mk = |u:u64, dom:usize| -> f32 { match dom {
            0 => f32::from_bits((u as u32 & 0x007FFFFF) | (0x3F000000)) - 0.75, // near [-0.75,1.25]
            1 => f32::from_bits(u as u32) , // fully random bits
